from math import gcd

def verify(witness):
    cutoff = witness["cutoff_m"]
    anchors = witness["anchors"]
    if cutoff != 8192:
        raise AssertionError("unexpected cutoff")
    def phi(m):
        return sum(1 for k in range(1, m + 1) if gcd(k, m) == 1)
    counts = {}
    for m in range(1, cutoff + 1):
        v = phi(m)
        counts[v] = counts.get(v, 0) + 1
    for n_str, expected in anchors.items():
        n = int(n_str)
        if counts.get(n, 0) != int(expected):
            raise AssertionError("anchor mismatch at n=%d: got %d, expected %d" % (n, counts.get(n, 0), int(expected)))
